def k(s): return ' <span class="k">%s</span>'%s if s else ''
def r(st,t,b='',lv=0):
    return '<div class="r%s"><span class="d %s"></span><span class="t">%s%s</span></div>'%((' s' if lv==1 else ' s2' if lv==2 else ''),st,t,k(b))
def c(cls,h,*rows,sub=''):
    return '<div class="c %s"><h2>%s</h2>%s%s</div>'%(cls,h,('<p class="sm">%s</p>'%sub) if sub else '',''.join(rows))
def it(t,b=''): return '<p class="it">%s%s</p>'%(t,k(b))
